def layout():
    return GROUPS, OBS_SIZE

def split_obs(buf, groups=GROUPS):
    out = {}
    for name, off, r, c in groups:
        a = buf[..., off:off + r * c]
        out[name] = a.reshape(buf.shape[:-1] + ((c,) if r == 1 else (r, c)))
    return out
